"""Build a self-contained Harbor bundle of step 1 from sources and prepared inputs."""

from __future__ import annotations

import argparse
import hashlib
import json
import shutil
import tomllib
from pathlib import Path
from typing import Any

from task_paths import EXPERIMENT_ROOT, STEP, TASK_ROOT

ROOT_FILES = ("task.toml",)
INPUT_DIRS = ("environment", STEP)
EXCLUDED_PARTS = {".venv", "__pycache__", ".pytest_cache", ".DS_Store", "experiment"}
# Prepared inputs, generated by scripts/builder and kept out of Git.
REQUIRED_PREPARED = (
    "environment/data/workspace.tar.gz",
    "environment/data/units.json",
    "environment/data/fsmaint.key",
    f"{STEP}/tests/private/skeleton.tar.gz",
    f"{STEP}/tests/private/sealed_tests.json",
    f"{STEP}/tests/private/vectors/inputs.pkl",
    f"{STEP}/tests/private/vectors/gold.json",
    f"{STEP}/tests/private/vectors/documented.json",
    f"{STEP}/tests/private/unit_bodies.json",
)
REQUIRED_REFERENCE_DIR = f"{STEP}/solution/data/sympy"
# Private lists carry the list and nothing else: no count, note or other key reaches the bundle.
PRIVATE_LIST_KEYS = {
    f"{STEP}/tests/private/sealed_tests.json": {"tests"},
    f"{STEP}/tests/private/vectors/documented.json": {"calls"},
}
# One source, staged into each image's own build context.
STAGED_COPIES = (
    ("common/restorelib.py", "environment/restore/lib/restorelib.py"),
    ("common/restorelib.py", f"{STEP}/tests/verifier/lib/restorelib.py"),
    ("environment/pyproject.toml", f"{STEP}/tests/runtime/pyproject.toml"),
    ("environment/data/units.json", f"{STEP}/tests/private/units.json"),
    ("environment/data/fsmaint.key", f"{STEP}/tests/private/fsmaint.key"),
)


def selected_files(task_root: Path) -> dict[str, Path]:
    """Select runtime files, leaving out authoring tools, notes and caches.

    Args:
        task_root: Source task with prepared inputs already in place.

    Returns:
        Bundle-relative names mapped to the source file for each.

    Raises:
        ValueError: A prepared input is missing, a private list holds more than its list,
            or an input is a symlink.
    """
    for required in REQUIRED_PREPARED:
        if not (task_root / required).is_file():
            raise ValueError(f"Prepare task data first; missing {required}")
    if not any((task_root / REQUIRED_REFERENCE_DIR).rglob("*.py")):
        raise ValueError(f"Prepare task data first; missing {REQUIRED_REFERENCE_DIR}")
    for relative, keys in PRIVATE_LIST_KEYS.items():
        try:
            data = json.loads((task_root / relative).read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise ValueError(f"{relative} is not readable JSON") from exc
        if not isinstance(data, dict) or set(data) != keys:
            found = sorted(data) if isinstance(data, dict) else type(data).__name__
            raise ValueError(f"{relative} must hold only {sorted(keys)}, not {found}")
    inputs = {name: task_root / name for name in ROOT_FILES}
    for directory in INPUT_DIRS:
        for path in (task_root / directory).rglob("*"):
            relative = path.relative_to(task_root)
            if EXCLUDED_PARTS.intersection(relative.parts):
                continue
            if path.is_symlink():
                raise ValueError(f"Bundle inputs cannot be symlinks: {path}")
            if path.is_file() and path.suffix != ".pyc":
                inputs[relative.as_posix()] = path
    for source, target in STAGED_COPIES:
        if not (task_root / source).is_file():
            raise ValueError(f"Missing shared source {source}")
        inputs[target] = task_root / source
    return dict(sorted(inputs.items()))


def package_step(task_root: Path, destination: Path) -> dict[str, Any]:
    """Stage a content-addressed bundle named after the declared task slug.

    Args:
        task_root: Authoring source directory.
        destination: Local output directory; private verifier inputs are included.

    Returns:
        The staged task path, its content hash and its file count. The README,
        checks/, scripts/, common/ and experiment/ are not in the bundle.

    Raises:
        ValueError: Inputs are unprepared or the task identity is malformed.
    """
    config = tomllib.loads((task_root / "task.toml").read_text(encoding="utf-8"))
    name = config.get("task", {}).get("name", "")
    if name.count("/") != 1:
        raise ValueError("Packaging requires [task].name in org/name form")
    if [step.get("name") for step in config.get("steps", [])] != [Path(STEP).name]:
        raise ValueError("The bundle must declare exactly step 1")
    task_slug = name.rsplit("/", 1)[-1]
    inputs = selected_files(task_root)
    hashes = {name: hashlib.sha256(path.read_bytes()).hexdigest() for name, path in inputs.items()}
    digest = hashlib.sha256(json.dumps(hashes, sort_keys=True).encode()).hexdigest()
    staging = destination / "bundles" / digest[:12] / task_slug
    if staging.exists():
        shutil.rmtree(staging)
    for name, path in inputs.items():
        target = staging / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)
    manifest = {"sha256": digest, "files": hashes}
    (staging.parent / "BUNDLE_MANIFEST.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    return {"task_path": str(staging.resolve()), "content_sha256": digest, "files": len(inputs)}


def main() -> None:
    """Package the task for preflight or upload and print the result as JSON.

    Raises:
        ValueError: Runtime inputs or the task identity are invalid.
        OSError: A source cannot be read or an output cannot be written.
    """
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=EXPERIMENT_ROOT / "dist")
    args = parser.parse_args()
    print(json.dumps(package_step(TASK_ROOT, args.output.resolve()), indent=2))


if __name__ == "__main__":
    main()
